export interface Quote {
  text: string;
  source: string;
  author: string;
}

export interface Level {
  name: string;
  tier: string; // The major rank group (e.g. 'Egg', 'Tadpole')
  minXP: number;
  color: string;
  shade: string;
  requiredWpm: number;
}

export interface GameState {
  xp: number;
  completedQuotes: number;
}

export interface TestResult {
  id: number;
  date: string;
  wpm: number;
  xpEarned: number;
  mode: GameMode;
}

export type MusicSource = 'NONE' | 'YOUTUBE' | 'SPOTIFY' | 'GENERATED';

export interface MusicConfig {
  source: MusicSource;
  presetId: string;
}

export interface Settings {
  ghostEnabled: boolean;
  readAheadEnabled: boolean;
  sfxEnabled: boolean;
  mechanicalSoundEnabled: boolean; // Toggle for typing sounds
  ambientVolume: number; // Volume for GENERATED sources (Brown Noise, Piano, etc.)
  musicConfig: MusicConfig;
  themeId: string; // New: Selected Theme ID
}

export type GameMode = 'QUOTES' | 'HARDCORE' | 'FIX_MISTAKE';

export enum GameStatus {
  IDLE = 'IDLE',
  PLAYING = 'PLAYING',
  COMPLETED = 'COMPLETED', // Successfully typed with 100% accuracy
  FAILED = 'FAILED', // Typed but mistakes were present at the end
}

export interface Theme {
  id: string;
  name: string;
  description: string;
  minTier: string; // Tier required to unlock (e.g. 'Tadpole')
  colors: {
    frog: Record<number, string>; // 50-900
    stone: Record<number, string>; // 50-900 (Used for neutrals)
    background: string;
  };
}

export interface Achievement {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  category: 'SPEED' | 'STREAK' | 'VOLUME' | 'MASTERY' | 'HIDDEN';
  condition: (stats: { wpm: number; totalQuotes: number; maxStreak: number; currentStreak: number; mode: GameMode }) => boolean;
}

class SoundEngine {
  private ctx: AudioContext | null = null;
  private enabled: boolean = true;
  private mechanicalEnabled: boolean = true;

  // Ambient/Generated Music components
  private ambientInterval: number | null = null;
  private ambientGain: GainNode | null = null;
  private ambientType: string = '';
  private ambientVolume: number = 0.5;

  // FX for Ambient
  private delayNode: DelayNode | null = null;
  private feedbackNode: GainNode | null = null;
  private lowpassNode: BiquadFilterNode | null = null;
  private compressorNode: DynamicsCompressorNode | null = null;

  // Cached Buffers (Optimization)
  private noiseBuffers: { [key: string]: AudioBuffer } = {};

  // Brown Noise specific (now part of ambient system)
  private brownNoiseSource: AudioBufferSourceNode | null = null;

  // Sequence State
  private seqIndex: number = 0;

  constructor() {
    try {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      // Pre-generate noise buffers to avoid GC stutter during playback
      if (this.ctx) {
        this.generateNoiseBuffer('white', 1.0); // 1 second of white noise
      }
    } catch (e) {
      console.warn("Web Audio API not supported");
    }
  }

  private generateNoiseBuffer(type: 'white', duration: number) {
    if (!this.ctx) return;
    const bufferSize = this.ctx.sampleRate * duration;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);

    for (let i = 0; i < bufferSize; i++) {
        // White noise
        data[i] = Math.random() * 2 - 1;
    }
    this.noiseBuffers[type] = buffer;
  }

  public setEnabled(enabled: boolean) {
    this.enabled = enabled;
  }

  public setMechanicalEnabled(enabled: boolean) {
    this.mechanicalEnabled = enabled;
  }

  public setAmbientVolume(volume: number) {
    this.ambientVolume = volume;
    if (this.ambientGain && this.ctx) {
        this.ambientGain.gain.setTargetAtTime(volume, this.ctx.currentTime, 0.2);
    }
  }

  public setAmbientMusic(presetId: string) {
    if (this.ambientType === presetId) return; // Already playing this preset

    this.stopAmbientMusic();

    if (presetId) {
      this.ambientType = presetId;
      this.startAmbientMusic();
    }
  }

  public stopAmbientMusic() {
    if (this.ambientInterval) {
      window.clearInterval(this.ambientInterval);
      this.ambientInterval = null;
    }

    // Fade out main ambient gain
    if (this.ambientGain && this.ctx) {
      const t = this.ctx.currentTime;
      this.ambientGain.gain.setValueAtTime(this.ambientGain.gain.value, t);
      this.ambientGain.gain.linearRampToValueAtTime(0, t + 1); 

      const oldGain = this.ambientGain;
      const oldSource = this.brownNoiseSource;

      setTimeout(() => {
        try { oldGain.disconnect(); } catch (e) {}
        if (oldSource) {
            try { oldSource.stop(); oldSource.disconnect(); } catch (e) {}
        }
      }, 1100);
    }

    this.ambientGain = null;
    this.brownNoiseSource = null;
    this.ambientType = '';
    this.seqIndex = 0;
  }

  private startAmbientMusic() {
    this.ensureContext();
    if (!this.ctx) return;

    // Master Gain for Ambient
    this.ambientGain = this.ctx.createGain();
    this.ambientGain.gain.value = this.ambientVolume;

    // Compressor to glue sounds together (especially drums)
    this.compressorNode = this.ctx.createDynamicsCompressor();
    this.compressorNode.threshold.value = -24;
    this.compressorNode.knee.value = 30;
    this.compressorNode.ratio.value = 12;
    this.compressorNode.attack.value = 0.003;
    this.compressorNode.release.value = 0.25;

    this.ambientGain.connect(this.compressorNode);
    this.compressorNode.connect(this.ctx.destination);

    // Common FX Chain
    this.delayNode = this.ctx.createDelay();
    this.delayNode.delayTime.value = 0.4; 

    this.feedbackNode = this.ctx.createGain();
    this.feedbackNode.gain.value = 0.3; 

    this.lowpassNode = this.ctx.createBiquadFilter();
    this.lowpassNode.type = 'lowpass';
    this.lowpassNode.frequency.value = 2500;

    this.delayNode.connect(this.feedbackNode);
    this.feedbackNode.connect(this.delayNode);
    this.delayNode.connect(this.lowpassNode);
    this.lowpassNode.connect(this.ambientGain);

    switch (this.ambientType) {
        case 'PIANO_BEETHOVEN':
            this.playBeethovenPiano();
            break;
        case 'PIANO_SATIE':
            this.playSatiePiano();
            break;
        case 'PIANO_JAZZ':
            this.playJazzPiano();
            break;
        case 'ZEN':
            this.playProceduralZen();
            break;
        case 'BROWN_NOISE':
            this.playBrownNoise();
            break;
        case 'GUITAR':
            this.playAcousticGuitar();
            break;
        case 'DRUMS_HARDCORE':
            this.playHardcoreDrums();
            break;
        case 'SYNTH_COSMIC':
            this.playCosmicSynth();
            break;
    }
  }

  // --- Brown Noise ---
  private playBrownNoise() {
    if (!this.ctx || !this.ambientGain) return;

    const bufferSize = 2 * this.ctx.sampleRate; 
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);

    let lastOut = 0;
    for (let i = 0; i < bufferSize; i++) {
        const white = Math.random() * 2 - 1;
        data[i] = (lastOut + (0.02 * white)) / 1.02;
        lastOut = data[i];
        data[i] *= 3.5; 
    }

    this.brownNoiseSource = this.ctx.createBufferSource();
    this.brownNoiseSource.buffer = buffer;
    this.brownNoiseSource.loop = true;

    // Separate filter for Brown Noise to make it cozy
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 400; 

    this.brownNoiseSource.connect(filter);
    filter.connect(this.ambientGain);

    this.brownNoiseSource.start(0);
  }

  // --- Piano Generators ---

  private playBeethovenPiano() {
    const Gs3 = 207.65; const Cs4 = 277.18; const E4 = 329.63;
    const A3 = 220.00; const D4 = 293.66; const Fs3 = 185.00;

    const sequence = [
        // Moonlight Sonata Arpeggios (Simplified)
        [Gs3, 0.6], [Cs4, 0.6], [E4, 0.6], 
        [Gs3, 0.6], [Cs4, 0.6], [E4, 0.6], 
        [A3, 0.6], [Cs4, 0.6], [E4, 0.6],
        [Fs3, 0.6], [A3, 0.6], [D4, 0.6],
    ];

    this.runSequence(sequence, (freq) => this.triggerPianoNote(freq, 'triangle'));
  }

  private playSatiePiano() {
    // Gymnopédie No.1 style (Slow 3/4)
    // Root, Chord, Chord pattern
    const Gmaj7 = [196.00, 246.94, 293.66, 369.99]; // G3, B3, D4, F#4
    const Dmaj7 = [146.83, 220.00, 277.18, 329.63]; // D3, A3, C#4, E4

    const sequence: any[] = [
        { notes: [98.00], duration: 1.5 }, // Low G2
        { notes: Gmaj7, duration: 1.5 },   // Chord
        { notes: Gmaj7, duration: 1.5 },   // Chord
        { notes: [73.42], duration: 1.5 }, // Low D2
        { notes: Dmaj7, duration: 1.5 },   // Chord
        { notes: Dmaj7, duration: 1.5 },   // Chord
    ];

    this.seqIndex = 0;
    const playNext = () => {
        if (!this.ambientType || !this.ctx) return;
        const step = sequence[this.seqIndex % sequence.length];
        this.seqIndex++;

        step.notes.forEach((freq: number) => {
            // Satie is softer, use sine/triangle mix
            this.triggerPianoNote(freq, 'sine', 0.15, 3.0);
        });

        this.ambientInterval = window.setTimeout(playNext, step.duration * 1000);
    };
    playNext();
  }

  private playJazzPiano() {
    // ii-V-I progressions with extensions
    const Dm9 = [293.66, 349.23, 415.30, 440.00, 523.25]; // D4, F4, G#4(b5), A4, C5
    const G13 = [196.00, 246.94, 329.63, 440.00]; 
    const Cmaj9 = [261.63, 329.63, 392.00, 493.88, 587.33];

    const chords = [Dm9, G13, Cmaj9];

    const playNext = () => {
        if (!this.ambientType || !this.ctx) return;

        // Randomly pick a chord
        const chord = chords[Math.floor(Math.random() * chords.length)];

        // Strum effect
        chord.forEach((freq, i) => {
            setTimeout(() => {
                this.triggerPianoNote(freq, 'triangle', 0.1, 1.5);
            }, i * 30); // 30ms strum delay
        });

        // Add a random high melody note occasionally
        if (Math.random() > 0.5) {
            setTimeout(() => {
                const scale = [523.25, 587.33, 659.25, 783.99, 880.00];
                const note = scale[Math.floor(Math.random() * scale.length)];
                this.triggerPianoNote(note, 'sine', 0.08, 1.0);
            }, 800);
        }

        const duration = 2000 + Math.random() * 2000;
        this.ambientInterval = window.setTimeout(playNext, duration);
    };
    playNext();
  }

  private triggerPianoNote(freq: number, type: OscillatorType = 'triangle', volume: number = 0.2, decay: number = 2.5) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;

    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);

    // Subtle detune for realism
    const osc2 = this.ctx.createOscillator();
    osc2.type = type;
    osc2.frequency.setValueAtTime(freq * 1.002, t);

    const env = this.ctx.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(volume, t + 0.05);
    env.gain.exponentialRampToValueAtTime(0.001, t + decay);

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(800, t);
    filter.frequency.linearRampToValueAtTime(100, t + decay);

    osc.connect(filter);
    osc2.connect(filter);
    filter.connect(env);

    env.connect(this.ambientGain);
    if (this.delayNode) env.connect(this.delayNode);

    osc.start(t);
    osc2.start(t);
    osc.stop(t + decay + 0.1);
    osc2.stop(t + decay + 0.1);

    setTimeout(() => { osc.disconnect(); osc2.disconnect(); env.disconnect(); filter.disconnect(); }, (decay + 0.2) * 1000);
  }

  // --- Guitar Generator ---

  private playAcousticGuitar() {
    const chords = [
        [196.00, 246.94, 293.66, 392.00], // G
        [164.81, 220.00, 261.63, 329.63], // C
        [146.83, 220.00, 293.66, 369.99], // D
        [130.81, 196.00, 261.63, 329.63]  // Em
    ];

    const playStrum = () => {
        if (!this.ambientType || !this.ctx) return;

        const chord = chords[Math.floor(Math.random() * chords.length)];

        // Arpeggiated finger picking pattern
        const pattern = [0, 2, 1, 3, 2, 1]; // string indices

        pattern.forEach((stringIdx, i) => {
            if (chord[stringIdx]) {
                const timeOffset = i * 250; // 8th notes at moderate tempo
                this.ambientInterval = window.setTimeout(() => {
                     this.triggerGuitarPluck(chord[stringIdx]);
                }, timeOffset);
            }
        });

        // Next bar
        this.ambientInterval = window.setTimeout(playStrum, 2000); // 1 bar duration roughly
    };
    playStrum();
  }

  private triggerGuitarPluck(freq: number) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;

    const osc = this.ctx.createOscillator();
    osc.type = 'sawtooth'; // Richer harmonics for strings
    osc.frequency.setValueAtTime(freq, t);

    const env = this.ctx.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(0.15, t + 0.02); // Sharp attack
    env.gain.exponentialRampToValueAtTime(0.001, t + 1.5); // Short decay

    // Filter envelope to simulate string "twang" dying out
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.Q.value = 1;
    filter.frequency.setValueAtTime(3000, t);
    filter.frequency.exponentialRampToValueAtTime(100, t + 0.5);

    osc.connect(filter);
    filter.connect(env);
    env.connect(this.ambientGain);
    if (this.delayNode) env.connect(this.delayNode);

    osc.start(t);
    osc.stop(t + 1.5);
    setTimeout(() => { osc.disconnect(); env.disconnect(); filter.disconnect(); }, 1600);
  }

  // --- Cosmic Synth ---

  private playCosmicSynth() {
    const scale = [130.81, 155.56, 196.00, 233.08, 261.63]; // Cm pentatonic

    const playPad = () => {
        if (!this.ambientType || !this.ctx) return;
        const freq = scale[Math.floor(Math.random() * scale.length)];
        this.triggerSynthPad(freq);

        // Drone bass
        if (Math.random() > 0.7) this.triggerSynthPad(65.41, 6.0); // Low C

        const nextTime = 4000 + Math.random() * 4000;
        this.ambientInterval = window.setTimeout(playPad, nextTime);
    };
    playPad();
  }

  private triggerSynthPad(freq: number, duration: number = 8.0) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;

    const osc1 = this.ctx.createOscillator();
    osc1.type = 'sawtooth';
    osc1.frequency.setValueAtTime(freq, t);

    const osc2 = this.ctx.createOscillator();
    osc2.type = 'square';
    osc2.frequency.setValueAtTime(freq * 1.01, t); // Detuned

    const lfo = this.ctx.createOscillator();
    lfo.frequency.value = 0.2; // Slow modulation
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.value = 400;

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 600;

    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);

    const env = this.ctx.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(0.15, t + 2.0); // Slow attack
    env.gain.linearRampToValueAtTime(0, t + duration); // Long release

    osc1.connect(filter);
    osc2.connect(filter);
    filter.connect(env);
    env.connect(this.ambientGain);
    // Heavy reverb via delay
    if (this.delayNode) {
        const send = this.ctx.createGain();
        send.gain.value = 0.6;
        env.connect(send);
        send.connect(this.delayNode);
    }

    osc1.start(t);
    osc2.start(t);
    lfo.start(t);
    osc1.stop(t + duration);
    osc2.stop(t + duration);
    lfo.stop(t + duration);

    setTimeout(() => { 
        osc1.disconnect(); osc2.disconnect(); lfo.disconnect(); env.disconnect(); 
    }, (duration + 1) * 1000);
  }

  // --- Hardcore Drums ---

  private playHardcoreDrums() {
    // 174 BPM approx
    const stepTime = 60 / 174 / 4; // 16th note duration

    let step = 0;
    const loop = () => {
        if (!this.ambientType || !this.ctx) return;

        const barStep = step % 16;

        // Kick Pattern (Amen-ish)
        if (barStep === 0 || barStep === 10) this.triggerKick();
        if (barStep === 2 && Math.random() > 0.5) this.triggerKick(0.5); // Ghost kick

        // Snare Pattern
        if (barStep === 4 || barStep === 12) this.triggerSnare();
        if (barStep === 15 && Math.random() > 0.7) this.triggerSnare(0.6); // Fill

        // Hi Hats (Fast)
        if (barStep % 2 === 0) this.triggerHat();
        if (Math.random() > 0.8) this.triggerHat(0.5); // Random shuffle

        step++;
        this.ambientInterval = window.setTimeout(loop, stepTime * 1000);
    };
    loop();
  }

  private triggerKick(vol: number = 1.0) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.frequency.setValueAtTime(150, t);
    osc.frequency.exponentialRampToValueAtTime(0.01, t + 0.5);

    gain.gain.setValueAtTime(vol * 0.8, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);

    osc.connect(gain);
    gain.connect(this.ambientGain);

    osc.start(t);
    osc.stop(t + 0.5);
    setTimeout(() => { osc.disconnect(); gain.disconnect(); }, 600);
  }

  private triggerSnare(vol: number = 1.0) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;

    // Reuse cached buffer if available
    if (!this.noiseBuffers['white']) this.generateNoiseBuffer('white', 1.0);
    const buffer = this.noiseBuffers['white'];

    const noise = this.ctx.createBufferSource();
    noise.buffer = buffer;

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.value = 1000;

    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(vol * 0.5, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.2);

    // Add a 'tonal' pop for the snare body
    const osc = this.ctx.createOscillator();
    osc.frequency.setValueAtTime(250, t);
    osc.frequency.exponentialRampToValueAtTime(100, t + 0.1);
    const oscGain = this.ctx.createGain();
    oscGain.gain.setValueAtTime(vol * 0.5, t);
    oscGain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);

    noise.connect(filter);
    filter.connect(gain);
    gain.connect(this.ambientGain);

    osc.connect(oscGain);
    oscGain.connect(this.ambientGain);

    noise.start(t);
    osc.start(t);
    noise.stop(t + 0.2);
    osc.stop(t + 0.2);

    setTimeout(() => { 
        noise.disconnect(); filter.disconnect(); gain.disconnect(); 
        osc.disconnect(); oscGain.disconnect();
    }, 300);
  }

  private triggerHat(vol: number = 1.0) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;

    // Reuse cached buffer
    if (!this.noiseBuffers['white']) this.generateNoiseBuffer('white', 1.0);
    const buffer = this.noiseBuffers['white'];

    const noise = this.ctx.createBufferSource();
    noise.buffer = buffer;

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.value = 5000;

    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(vol * 0.2, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.05);

    noise.connect(filter);
    filter.connect(gain);
    gain.connect(this.ambientGain);

    noise.start(t);
    noise.stop(t + 0.05);
    setTimeout(() => { noise.disconnect(); filter.disconnect(); gain.disconnect(); }, 100);
  }

  // --- Zen Bells ---
  private playProceduralZen() {
    const scale = [523.25, 587.33, 659.25, 783.99, 880.00]; // C major pentatonic

    const playNote = () => {
      if (!this.ctx || !this.ambientGain) return;
      const freq = scale[Math.floor(Math.random() * scale.length)];
      this.triggerBellNote(freq);
    };

    playNote();

    const scheduleNext = () => {
       if (!this.ambientType) return;
       const delay = 4000 + Math.random() * 4000;
       this.ambientInterval = window.setTimeout(() => {
          playNote();
          scheduleNext();
       }, delay);
    };
    scheduleNext();
  }

  private triggerBellNote(freq: number) {
    if (!this.ctx || !this.ambientGain) return;
    const t = this.ctx.currentTime;

    const osc = this.ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, t);

    const modulator = this.ctx.createOscillator();
    modulator.type = 'sine';
    modulator.frequency.setValueAtTime(freq * 2.5, t); 
    const modGain = this.ctx.createGain();
    modGain.gain.setValueAtTime(freq * 0.5, t);
    modGain.gain.exponentialRampToValueAtTime(0.01, t + 2);

    modulator.connect(modGain);
    modGain.connect(osc.frequency);

    const env = this.ctx.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(0.1, t + 0.02);
    env.gain.exponentialRampToValueAtTime(0.001, t + 4.0);

    osc.connect(env);
    env.connect(this.ambientGain);
    if (this.delayNode) env.connect(this.delayNode);

    osc.start(t);
    modulator.start(t);
    osc.stop(t + 4.0);
    modulator.stop(t + 4.0);

    setTimeout(() => {
        osc.disconnect();
        modulator.disconnect();
        env.disconnect();
    }, 4100);
  }

  // --- Global Helpers ---

  private runSequence(sequence: any[], playFn: (f: number) => void) {
    const playNextNote = () => {
        if (!this.ambientType || !this.ctx) return;
        const noteData = sequence[this.seqIndex % sequence.length];
        this.seqIndex++;
        playFn(noteData[0]);
        const duration = noteData[1] * 1000; 
        this.ambientInterval = window.setTimeout(playNextNote, duration);
    };
    this.seqIndex = 0;
    playNextNote();
  }

  public resumeContext() {
    this.ensureContext();
  }

  private ensureContext() {
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  public playKeypress() {
     if (!this.enabled || !this.mechanicalEnabled || !this.ctx) return;
     this.ensureContext();
     const t = this.ctx.currentTime;

     // 1. The "Thud" (Body) - Low triangle wave for tactile thud
     const osc = this.ctx.createOscillator();
     osc.type = 'triangle';
     // Randomize pitch slightly for organic feel
     osc.frequency.setValueAtTime(300 + Math.random()*50, t);
     osc.frequency.exponentialRampToValueAtTime(50, t + 0.08);

     const oscGain = this.ctx.createGain();
     oscGain.gain.setValueAtTime(0.4, t);
     oscGain.gain.exponentialRampToValueAtTime(0.01, t + 0.08);

     osc.connect(oscGain);
     oscGain.connect(this.ctx.destination);
     osc.start(t);
     osc.stop(t + 0.1);

     // 2. The "Click" (Switch) - Filtered white noise
     // Reuse white noise buffer if available
     if (!this.noiseBuffers['white']) this.generateNoiseBuffer('white', 1.0);
     const noise = this.ctx.createBufferSource();
     noise.buffer = this.noiseBuffers['white'];

     const noiseFilter = this.ctx.createBiquadFilter();
     noiseFilter.type = 'lowpass';
     noiseFilter.frequency.setValueAtTime(2000, t); // Dampen high hiss

     const noiseGain = this.ctx.createGain();
     noiseGain.gain.setValueAtTime(0.15, t);
     noiseGain.gain.exponentialRampToValueAtTime(0.001, t + 0.05);

     noise.connect(noiseFilter);
     noiseFilter.connect(noiseGain);
     noiseGain.connect(this.ctx.destination);
     noise.start(t);
     noise.stop(t + 0.05);
  }

  public playError() {
    if (!this.enabled || !this.ctx) return;
    this.ensureContext();

    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(150, t);
    osc.frequency.linearRampToValueAtTime(100, t + 0.1);

    gain.gain.setValueAtTime(0.3, t);
    gain.gain.exponentialRampToValueAtTime(0.01, t + 0.2);

    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start(t);
    osc.stop(t + 0.2);
  }

  public playSuccess() {
    if (!this.enabled || !this.ctx) return;
    this.ensureContext();
    const t = this.ctx.currentTime;

    [523.25, 659.25, 783.99].forEach((freq, i) => {
        const osc = this.ctx!.createOscillator();
        const gain = this.ctx!.createGain();

        osc.type = 'sine';
        osc.frequency.value = freq;
        gain.gain.setValueAtTime(0.05, t);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);

        osc.connect(gain);
        gain.connect(this.ctx!.destination);
        osc.start(t);
        osc.stop(t + 0.3);
    });
  }

  public playLevelUp() {
    if (!this.enabled || !this.ctx) return;
    this.ensureContext();
    const t = this.ctx.currentTime;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'triangle';
    osc.frequency.setValueAtTime(220, t);
    osc.frequency.exponentialRampToValueAtTime(880, t + 0.4);

    gain.gain.setValueAtTime(0.1, t);
    gain.gain.linearRampToValueAtTime(0, t + 0.4);

    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start(t);
    osc.stop(t + 0.4);

    for(let i=0; i<6; i++) {
        setTimeout(() => {
            const spark = this.ctx!.createOscillator();
            const sgain = this.ctx!.createGain();
            spark.type = 'sine';
            spark.frequency.value = 880 + (i*200);
            sgain.gain.setValueAtTime(0.05, this.ctx!.currentTime);
            sgain.gain.exponentialRampToValueAtTime(0.001, this.ctx!.currentTime + 0.2);
            spark.connect(sgain);
            sgain.connect(this.ctx!.destination);
            spark.start();
            spark.stop(this.ctx!.currentTime + 0.2);
        }, i * 60);
    }
  }
}

export const soundEngine = new SoundEngine();

import React, { useState, useEffect, useCallback, useLayoutEffect } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import HelpModal from './components/HelpModal';
import StatsModal from './components/StatsModal';
import ThemeModal from './components/ThemeModal';
import AchievementsModal from './components/AchievementsModal';
import AchievementToast from './components/AchievementToast';
import { MusicPlayer } from './components/MusicPlayer';
import { Quote, Settings, GameMode, TestResult } from './types';
import { fetchQuotes } from './services/quoteService';
import { getCurrentLevel, getNextLevel, calculateXP, getAverageWPM, LEVELS } from './utils/gameLogic';
import { soundEngine } from './utils/soundEngine';
import { Loader2, Settings as SettingsIcon, Music, CircleHelp, Skull, BookOpen, Eraser, TrendingUp, Palette, Award } from 'lucide-react';
import confetti from 'canvas-confetti';
import { THEMES } from './data/themes';
import { ACHIEVEMENTS } from './data/achievements';

const App: React.FC = () => {
  // Renamed to userXP and frogXP per specification
  const [userXP, setUserXP] = useState<number>(() => {
    const saved = localStorage.getItem('frogXP');
    // Fallback to legacy key if new key doesn't exist
    const legacy = localStorage.getItem('frogType_xp');
    if (saved) return parseInt(saved, 10);
    if (legacy) return parseInt(legacy, 10);
    return 0;
  });

  const [streak, setStreak] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_streak');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [unlockedAchievements, setUnlockedAchievements] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_achievements');
    return saved ? JSON.parse(saved) : [];
  });

  const [newlyUnlockedIds, setNewlyUnlockedIds] = useState<string[]>([]);

  // Track history for average WPM calculation (Last 10)
  const [wpmHistory, setWpmHistory] = useState<number[]>(() => {
    const saved = localStorage.getItem('frogType_wpmHistory');
    return saved ? JSON.parse(saved) : [];
  });

  // Track full history of tests
  const [testHistory, setTestHistory] = useState<TestResult[]>(() => {
    const saved = localStorage.getItem('frogType_history');
    return saved ? JSON.parse(saved) : [];
  });

  // Legacy single WPM tracker (kept for backward compatibility/reference if needed)
  const [lastWpm, setLastWpm] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_lastWpm');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [mistakePool, setMistakePool] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_mistakes');
    return saved ? JSON.parse(saved) : [];
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('frogType_settings');
    const parsed = saved ? JSON.parse(saved) : {};

    // Migration: If legacy brown noise was enabled, set it as active music
    const legacyBrownNoiseEnabled = parsed.brownNoiseEnabled === true;
    // Migration: Handle renaming brownNoiseVolume to ambientVolume
    const legacyVolume = parsed.brownNoiseVolume ?? 0.5;

    // Construct initial music config
    let initialMusicConfig = parsed.musicConfig || { source: 'NONE', presetId: '' };
    if (legacyBrownNoiseEnabled && initialMusicConfig.source === 'NONE') {
        initialMusicConfig = { source: 'GENERATED', presetId: 'BROWN_NOISE' };
    }

    return { 
      ghostEnabled: false, 
      readAheadEnabled: false, 
      sfxEnabled: true,
      mechanicalSoundEnabled: parsed.mechanicalSoundEnabled ?? true,
      ambientVolume: parsed.ambientVolume ?? legacyVolume, 
      musicConfig: initialMusicConfig,
      themeId: parsed.themeId || 'CLASSIC',
      ...parsed
    };
  });

  const [gameMode, setGameMode] = useState<GameMode>(() => {
    const saved = localStorage.getItem('frogType_gameMode');
    return (saved as GameMode) || 'QUOTES';
  });

  const [completedQuotes, setCompletedQuotes] = useState<string[]>(() => {
    const saved = localStorage.getItem('frogType_completedQuotes');
    return saved ? JSON.parse(saved) : [];
  });

  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);

  // Initialize currentQuote from storage if it exists (Memory Feature)
  const [currentQuote, setCurrentQuote] = useState<Quote | null>(() => {
    const saved = localStorage.getItem('frogType_currentQuote');
    return saved ? JSON.parse(saved) : null;
  });

  const [loading, setLoading] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isMusicOpen, setIsMusicOpen] = useState(false);
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isStatsOpen, setIsStatsOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isAchievementsOpen, setIsAchievementsOpen] = useState(false);

  // Persistence
  useEffect(() => { localStorage.setItem('frogXP', userXP.toString()); }, [userXP]);
  useEffect(() => { localStorage.setItem('frogType_streak', streak.toString()); }, [streak]);
  useEffect(() => { localStorage.setItem('frogType_lastWpm', lastWpm.toString()); }, [lastWpm]);
  useEffect(() => { localStorage.setItem('frogType_wpmHistory', JSON.stringify(wpmHistory)); }, [wpmHistory]);
  useEffect(() => { localStorage.setItem('frogType_history', JSON.stringify(testHistory)); }, [testHistory]);
  useEffect(() => { localStorage.setItem('frogType_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('frogType_mistakes', JSON.stringify(mistakePool)); }, [mistakePool]);
  useEffect(() => { localStorage.setItem('frogType_gameMode', gameMode); }, [gameMode]);
  useEffect(() => { localStorage.setItem('frogType_completedQuotes', JSON.stringify(completedQuotes)); }, [completedQuotes]);
  useEffect(() => { localStorage.setItem('frogType_achievements', JSON.stringify(unlockedAchievements)); }, [unlockedAchievements]);

  // Audio Settings Sync
  useEffect(() => {
    soundEngine.setEnabled(settings.sfxEnabled);
    soundEngine.setMechanicalEnabled(settings.mechanicalSoundEnabled);
    soundEngine.setAmbientVolume(settings.ambientVolume);

    // Sync Procedural Music
    if (settings.musicConfig.source === 'GENERATED') {
      soundEngine.setAmbientMusic(settings.musicConfig.presetId);
    } else {
      soundEngine.stopAmbientMusic();
    }
  }, [settings.sfxEnabled, settings.mechanicalSoundEnabled, settings.ambientVolume, settings.musicConfig]);

  // Apply Theme CSS Variables
  useLayoutEffect(() => {
    const theme = THEMES.find(t => t.id === settings.themeId) || THEMES[0];
    const root = document.documentElement;

    // Set Background
    root.style.setProperty('--bg-body', theme.colors.background);

    // Set Frog Palettes (50-900)
    Object.entries(theme.colors.frog).forEach(([key, value]) => {
       root.style.setProperty(`--frog-${key}`, value);
    });

    // Set Stone Palettes (50-900) - Maps to text/ui neutrals
    Object.entries(theme.colors.stone).forEach(([key, value]) => {
       root.style.setProperty(`--stone-${key}`, value);
    });

    // Derive body text color from stone palette (usually 700 or 800)
    // In inverted palettes (dark mode), 800 is Light, so this works nicely.
    root.style.setProperty('--text-body', theme.colors.stone[800]);

  }, [settings.themeId]);

  // Handle Audio Context Auto-Resume on User Interaction
  useEffect(() => {
    const handleInteraction = () => {
      soundEngine.resumeContext();
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };

    window.addEventListener('click', handleInteraction);
    window.addEventListener('keydown', handleInteraction);
    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };
  }, []);

  // Persist Current Quote - Don't let user load other quotes until complete
  useEffect(() => { 
    if (currentQuote) {
      localStorage.setItem('frogType_currentQuote', JSON.stringify(currentQuote)); 
    } else {
      localStorage.removeItem('frogType_currentQuote');
    }
  }, [currentQuote]);

  // Generate a quote from mistakes
  const generateMistakeQuote = useCallback((): Quote | null => {
    if (mistakePool.length === 0) return null;

    // Create a working pool
    let pool = [...mistakePool];

    // If the pool is small (less than 15 words), repeat existing words
    // to ensure the practice session has enough content.
    while (pool.length < 15) {
       pool = [...pool, ...mistakePool];
    }

    // Shuffle and pick up to 15 words
    const shuffled = pool.sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, 15);
    const text = selected.join(' ');

    return {
      text,
      source: "Personal Training",
      author: "Your Mistakes"
    };
  }, [mistakePool]);

  const loadMoreQuotes = useCallback(async () => {
    try {
      const newQuotes = await fetchQuotes(5, completedQuotes);
      setQuotesQueue(prev => [...prev, ...newQuotes]);
    } catch (error) {
      console.error("Failed to load quotes", error);
    }
  }, [completedQuotes]);

  // Initial Load
  useEffect(() => {
    const init = async () => {
      if (!currentQuote && quotesQueue.length === 0) {
         setLoading(true);
         await loadMoreQuotes();
         setLoading(false);
      } else if (quotesQueue.length < 3) {
         loadMoreQuotes();
      }
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Quote Management Logic
  useEffect(() => {
    if (currentQuote) return;

    if (gameMode === 'FIX_MISTAKE') {
      const mistakeQuote = generateMistakeQuote();
      if (mistakeQuote) {
        setCurrentQuote(mistakeQuote);
      } else {
        setGameMode('QUOTES'); 
      }
    } else {
      if (quotesQueue.length > 0) {
        const next = quotesQueue[0];
        setCurrentQuote(next);
        setQuotesQueue(prev => prev.slice(1));
      }

      if (quotesQueue.length < 3 && quotesQueue.length > 0) {
        loadMoreQuotes();
      }
    }
  }, [currentQuote, quotesQueue, gameMode, generateMistakeQuote, loadMoreQuotes]);

  const checkAchievements = (wpm: number) => {
    const newUnlocks: string[] = [];
    const stats = {
       wpm,
       totalQuotes: completedQuotes.length + 1, // Include current
       maxStreak: Math.max(streak + 1, streak + 1), // Simplification: we don't track max streak historically yet, but curr streak is rising
       currentStreak: streak + 1,
       mode: gameMode
    };

    ACHIEVEMENTS.forEach(ach => {
       if (!unlockedAchievements.includes(ach.id)) {
           if (ach.condition(stats)) {
               newUnlocks.push(ach.id);
           }
       }
    });

    if (newUnlocks.length > 0) {
       setUnlockedAchievements(prev => [...prev, ...newUnlocks]);
       setNewlyUnlockedIds(prev => [...prev, ...newUnlocks]);
       soundEngine.playLevelUp(); // Re-use level up sound for achievement
    }
  };

  const handleQuoteComplete = (xpCalc: number, wpm: number) => {
    // We rely on the component's calculation which includes streak and perfect bonuses
    let finalXp = xpCalc;

    // Hardcore Mode Reward: 5x XP (applied on top of component calculation)
    if (gameMode === 'HARDCORE') {
      finalXp = finalXp * 5;
    }

    // Fix Mistake Mode: Remove words from pool
    if (gameMode === 'FIX_MISTAKE' && currentQuote) {
      // Logic assumes typed text matches quote text perfectly (since complete)
      // We look for words in the generated text (which might contain duplicates)
      const wordsFixed = [...new Set(currentQuote.text.split(' '))]; // unique words in this specific session
      setMistakePool(prev => prev.filter(word => !wordsFixed.includes(word)));
    }

    // Remember completed quote to avoid repetition
    if (currentQuote && gameMode === 'QUOTES') {
       setCompletedQuotes(prev => [...prev, currentQuote.text]);
    }

    // Update WPM History (Last 10)
    const newHistory = [...wpmHistory, wpm].slice(-10); 
    setWpmHistory(newHistory);
    const avgWpm = getAverageWPM(newHistory);

    // Save Full History
    const newTestResult: TestResult = {
      id: Date.now(),
      date: new Date().toISOString(),
      wpm,
      xpEarned: finalXp,
      mode: gameMode
    };
    setTestHistory(prev => [...prev, newTestResult]);

    // Check Achievements
    checkAchievements(wpm);

    setUserXP(prev => {
      const currentLevel = getCurrentLevel(prev);
      const nextLevel = getNextLevel(currentLevel);
      let potentialXp = prev + finalXp;

      // Dual-Gate Logic: Speed and Mastery
      if (nextLevel && potentialXp >= nextLevel.minXP) {
         // Re-calculate mistake count based on optimistic update
         let effectiveMistakeCount = mistakePool.length;
         if (gameMode === 'FIX_MISTAKE' && currentQuote) {
             const wordsFixed = [...new Set(currentQuote.text.split(' '))];
             effectiveMistakeCount = mistakePool.filter(word => !wordsFixed.includes(word)).length;
         }

         const isMasteryGated = effectiveMistakeCount > 0;
         const isSpeedGated = avgWpm < nextLevel.requiredWpm;

         if (isMasteryGated) {
            return nextLevel.minXP - 1; // Cap due to Mastery
         }
         if (isSpeedGated) {
            return nextLevel.minXP - 1; // Cap due to Speed
         }
      }

      // Check if user Leveled Up (and wasn't gated)
      const newLevel = getCurrentLevel(potentialXp);

      // Only play fanfare if the TIER changes (e.g. Egg -> Tadpole)
      if (newLevel.tier !== currentLevel.tier && potentialXp >= newLevel.minXP) {
          // Bigger Confetti for Level Up!
          setTimeout(() => {
              confetti({
                particleCount: 200,
                spread: 120,
                origin: { y: 0.6 },
                colors: ['#d1fae5', '#10b981', '#fbbf24', '#f59e0b'],
                startVelocity: 45
              });
              soundEngine.playLevelUp(); // Distinct level up sound
          }, 300);
      }

      return potentialXp;
    });

    setStreak(prev => prev + 1);
    setLastWpm(wpm);
    setCurrentQuote(null); // Triggers effect to pop next quote and clear storage
  };

  const handleQuoteFail = () => {
    setStreak(0);
  };

  const handleMistake = (word?: string) => {
    // 1. Penalty Logic:
    // Hardcore: Lose 50% of total points
    // Standard/Fix: Lose 15% of total points
    const penaltyMultiplier = gameMode === 'HARDCORE' ? 0.5 : 0.85;
    setUserXP(prev => Math.floor(prev * penaltyMultiplier));

    // 2. Streak Reset Logic: Streak ends on error
    setStreak(0);

    // 3. Save Mistake Word
    if (word && word.length > 1) {
       setMistakePool(prev => {
         if (prev.includes(word)) return prev;
         return [...prev, word];
       });
    }
  };

  const toggleSettings = () => setIsSettingsOpen(!isSettingsOpen);
  const toggleMusic = () => setIsMusicOpen(!isMusicOpen);
  const toggleHelp = () => setIsHelpOpen(!isHelpOpen);
  const toggleStats = () => setIsStatsOpen(!isStatsOpen);
  const toggleTheme = () => setIsThemeOpen(!isThemeOpen);
  const toggleAchievements = () => setIsAchievementsOpen(!isAchievementsOpen);

  const switchMode = (mode: GameMode) => {
    if (mode === 'FIX_MISTAKE' && mistakePool.length === 0) return;
    setGameMode(mode);
    setCurrentQuote(null); // Reset current quote to force fetch new type
  };

  const clearToast = useCallback(() => {
    setNewlyUnlockedIds(prev => prev.slice(1));
  }, []);

  return (
    <div className="min-h-screen flex flex-col bg-transparent text-stone-800 font-sans selection:bg-frog-200">
      {/* Top Bar Navigation */}
      <header className="w-full bg-stone-50/80 backdrop-blur-md border-b border-stone-200 sticky top-0 z-40 px-6 py-4 shadow-sm transition-all">
        <div className="max-w-[1400px] mx-auto flex flex-col xl:flex-row items-center justify-between gap-4 xl:gap-8">

          {/* Group 1: Logo & Modes */}
          <div className="flex flex-col md:flex-row items-center gap-6 md:gap-8 w-full xl:w-auto">
            {/* Logo */}
            <div className="flex flex-col items-center md:items-start flex-shrink-0">
              <h1 className="text-xl font-black text-frog-800 tracking-tight flex items-center gap-2">
                <span className="text-2xl">🐸</span> Frog Type
              </h1>
            </div>

            {/* Game Mode Selector */}
            <div className="flex gap-1 p-1 bg-stone-100/80 rounded-lg shadow-inner border border-stone-200/50">
              <button 
                  onClick={() => switchMode('QUOTES')}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all ${gameMode === 'QUOTES' ? 'bg-white text-frog-600 shadow-sm ring-1 ring-stone-200' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  <BookOpen className="w-3.5 h-3.5" /> Quotes
              </button>
              <button 
                  onClick={() => switchMode('HARDCORE')}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all ${gameMode === 'HARDCORE' ? 'bg-stone-800 text-white shadow-sm ring-1 ring-stone-900' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}`}
              >
                  <Skull className="w-3.5 h-3.5" /> Hardcore
              </button>
              <button 
                  onClick={() => switchMode('FIX_MISTAKE')}
                  disabled={mistakePool.length === 0}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold flex items-center gap-1.5 transition-all 
                    ${gameMode === 'FIX_MISTAKE' ? 'bg-red-500 text-white shadow-sm ring-1 ring-red-600' : 'text-stone-400 hover:bg-stone-200/50 hover:text-stone-600'}
                    ${mistakePool.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}
                  `}
                  title={mistakePool.length === 0 ? "No mistakes recorded yet" : `${mistakePool.length} words to fix`}
              >
                  <Eraser className="w-3.5 h-3.5" /> Fix ({mistakePool.length})
              </button>
            </div>
          </div>

          {/* Group 2: Progress & Tools */}
          <div className="w-full xl:w-auto xl:flex-grow xl:max-w-2xl flex items-center gap-4 justify-end">
             {/* Pass Avg WPM and Mistake Count to ProgressBar */}
             <ProgressBar 
               xp={userXP} 
               avgWpm={getAverageWPM(wpmHistory)} 
               mistakeCount={mistakePool.length} 
             />

             <div className="flex items-center gap-1.5 border-l border-stone-200 pl-4 ml-2 shrink-0">
               <button 
                 onClick={toggleAchievements} 
                 className={`p-2 rounded-full transition-colors ${isAchievementsOpen ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Achievements"
               >
                  <Award className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleTheme} 
                 className={`p-2 rounded-full transition-colors ${isThemeOpen ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Themes"
               >
                  <Palette className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleStats} 
                 className={`p-2 rounded-full transition-colors ${isStatsOpen ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Statistics & History"
               >
                  <TrendingUp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleHelp} 
                 className={`p-2 rounded-full transition-colors ${isHelpOpen ? 'bg-stone-100 text-stone-700' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="How to Play"
               >
                  <CircleHelp className="w-5 h-5" />
               </button>
               <button 
                 onClick={toggleMusic} 
                 className={`p-2 rounded-full transition-colors ${isMusicOpen || settings.musicConfig.source !== 'NONE' ? 'bg-stone-100 text-frog-600' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-100'}`}
                 title="Background Music"
               >
                  <Music className="w-5 h-5" />
               </button>
               <button onClick={toggleSettings} className="p-2 hover:bg-stone-100 rounded-full text-stone-400 hover:text-stone-600 transition-colors">
                  <SettingsIcon className="w-5 h-5" />
               </button>
             </div>
          </div>

        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full relative">

        <div className="w-full flex items-center justify-center min-h-[60vh]">
          {loading && !currentQuote ? (
            <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Hatching quotes...</p>
            </div>
          ) : currentQuote ? (
            <TypingArea 
              quote={currentQuote} 
              onComplete={handleQuoteComplete} 
              onFail={handleQuoteFail}
              onMistake={handleMistake}
              onRequestNewQuote={() => setCurrentQuote(null)}
              streak={streak}
              ghostWpm={getAverageWPM(wpmHistory)}
              settings={settings}
              gameMode={gameMode}
              onInteract={() => setIsMusicOpen(false)}
            />
          ) : (
             <div className="flex flex-col items-center justify-center text-stone-400">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Fetching wisdom...</p>
            </div>
          )}
        </div>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={settings} 
        setSettings={setSettings} 
      />

      <ThemeModal
        isOpen={isThemeOpen}
        onClose={() => setIsThemeOpen(false)}
        currentThemeId={settings.themeId}
        setThemeId={(id) => setSettings({ ...settings, themeId: id })}
        currentLevel={getCurrentLevel(userXP)}
        allLevels={LEVELS}
      />

      <AchievementsModal
        isOpen={isAchievementsOpen}
        onClose={() => setIsAchievementsOpen(false)}
        unlockedIds={unlockedAchievements}
      />

      <AchievementToast 
        newlyUnlockedIds={newlyUnlockedIds}
        onClear={clearToast}
      />

      <HelpModal
        isOpen={isHelpOpen}
        onClose={() => setIsHelpOpen(false)}
      />

      <StatsModal
        isOpen={isStatsOpen}
        onClose={() => setIsStatsOpen(false)}
        avgWpm={getAverageWPM(wpmHistory)}
        history={testHistory}
      />

      {/* Music Player Widget */}
      <MusicPlayer 
        isOpen={isMusicOpen} 
        onClose={() => setIsMusicOpen(false)} 
        settings={settings}
        setSettings={setSettings}
      />

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

