      ...settings,
      musicConfig: { source: 'NONE', presetId: '' }
    });
  };

  const handleAmbientVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSettings({ ...settings, ambientVolume: parseFloat(e.target.value) });
